/// Arsenal's patch: Crystal Optimizer is on.
pub(crate) static ARSENAL_CRYSTAL_OPT: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// End crystals, lit TNT and item cooldowns as a native mod reads them (Arsenal's patch).
#[allow(dead_code)]
#[derive(Clone, Debug, Default)]
pub(crate) struct ArsenalWorld {
    pub(crate) crystals: Vec<[f64; 3]>,
    /// Position and fuse ticks left.
    pub(crate) tnts: Vec<([f64; 3], i32)>,
    /// Item id and how much of its cooldown is left (0..1); only items on cooldown.
    pub(crate) cooldowns: Vec<(String, f32)>,
    /// Dropped items: where, the item, how many.
    pub(crate) dropped: Vec<([f64; 3], String, u32)>,
    /// The item you're using (drawing a bow, eating) and for how many ticks.
    pub(crate) using: Option<(String, u32)>,
}

/// End crystals, lit TNT and item cooldowns (Arsenal's patch).
pub(super) fn arsenal_world(&self) -> ArsenalWorld {
    ArsenalWorld {
        crystals: self.crystals.iter().map(|c| [c.position.x as f64, c.position.y as f64, c.position.z as f64]).collect(),
        tnts: self.tnts.iter().map(|t| ([t.position.x as f64, t.position.y as f64, t.position.z as f64], t.fuse)).collect(),
        cooldowns: ["minecraft:ender_pearl", "minecraft:chorus_fruit", "minecraft:wind_charge", "minecraft:shield", "minecraft:mace", "minecraft:goat_horn"]
            .iter()
            .map(|id| (id.to_string(), self.cooldowns.percent(id, 0.0)))
            .filter(|c| c.1 > 0.0)
            .collect(),
        dropped: self.dropped.iter().take(300).map(|e| ([e.position.x as f64, e.position.y as f64, e.position.z as f64], e.stack.item.to_string(), e.stack.count)).collect(),
        using: self.using.and_then(|(slot, ticks)| {
            let stack = self.inventory.get(slot).and_then(|s| s.as_ref()).or(self.offhand.as_ref())?;
            Some((stack.item.to_string(), ticks))
        }),
    }
}

